package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;import net.minecraftforge.network.*;import net.minecraftforge.network.simple.SimpleChannel;import java.util.*;import java.lang.reflect.*;
/** Bounded inspection of Forge-owned channel graphs; never constructs discovered messages. */
public final class ModPacketCatalog {
 public record Message(String channel,int id,String direction,Class<?> type,SimpleChannel sender){}
 private static List<Message> messages=List.of();private static long loaded;private static JsonObject coverage=Jsons.obj("complete",false);
 public static List<Message> entries(){if(System.currentTimeMillis()-loaded>30000)refresh();return messages;}
 public static JsonObject coverage(){return coverage.deepCopy();}
 public static void refresh(){List<Message> result=new ArrayList<>();int blocked=0,channels=0;JsonArray unresolved=new JsonArray();try{Field f=NetworkRegistry.class.getDeclaredField("instances");f.setAccessible(true);Map<?,?> roots=(Map<?,?>)f.get(null);for(Object raw:new ArrayList<>(roots.values())){NetworkInstance instance=(NetworkInstance)raw;SimpleChannel channel=null;Set<Object> seen=Collections.newSetFromMap(new IdentityHashMap<>());record Node(Object value,int depth){}ArrayDeque<Node> pending=new ArrayDeque<>();pending.add(new Node(raw,0));int visited=0;while(!pending.isEmpty()&&visited++<1024){Node n=pending.poll();Object value=n.value();if(value==null||!seen.add(value))continue;if(value instanceof SimpleChannel s){channel=s;break;}if(n.depth()>6)continue;if(value instanceof Map<?,?> map){for(var e:map.entrySet()){if(pending.size()>2048)break;if(e.getKey()!=null)pending.add(new Node(e.getKey(),n.depth()+1));if(e.getValue()!=null)pending.add(new Node(e.getValue(),n.depth()+1));}}else if(value instanceof Iterable<?> list){for(Object e:list){if(pending.size()>2048)break;if(e!=null)pending.add(new Node(e,n.depth()+1));}}else if(value.getClass().getName().startsWith("net.minecraftforge.")||value.getClass().isSynthetic()){for(Class<?> c=value.getClass();c!=null&&c!=Object.class;c=c.getSuperclass())for(Field field:c.getDeclaredFields()){if(Modifier.isStatic(field.getModifiers())||field.getType().isPrimitive())continue;try{field.setAccessible(true);Object child=field.get(value);if(child!=null&&pending.size()<2048)pending.add(new Node(child,n.depth()+1));}catch(Exception ex){blocked++;}}}}
   if(channel==null){unresolved.add(instance.getChannelName().toString());continue;}channels++;Field codecField=SimpleChannel.class.getDeclaredField("indexedCodec");codecField.setAccessible(true);Object codec=codecField.get(channel);Field typesField=codec.getClass().getDeclaredField("types");typesField.setAccessible(true);for(Object handler:((Map<?,?>)typesField.get(codec)).values()){if(result.size()>=8192)break;Class<?> type=handler.getClass();Field message=type.getDeclaredField("messageType"),id=type.getDeclaredField("index"),direction=type.getDeclaredField("networkDirection");message.setAccessible(true);id.setAccessible(true);direction.setAccessible(true);String d=((Optional<?>)direction.get(handler)).map(Object::toString).orElse("unknown");if(!d.startsWith("LOGIN"))result.add(new Message(instance.getChannelName().toString(),id.getInt(handler),d,(Class<?>)message.get(handler),channel));}}}catch(Exception ex){coverage.addProperty("error",ex.getClass().getSimpleName());}messages=List.copyOf(result);loaded=System.currentTimeMillis();coverage=Jsons.obj("complete",false,"simple_channels",channels,"inaccessible",blocked,"unresolved",unresolved,"limitations","bounded Forge SimpleChannel graph; custom transports may be absent");}
 public static Message find(Class<?> type,String channel){List<Message> matches=entries().stream().filter(m->m.type()==type&&(channel.isEmpty()||m.channel().equals(channel))).toList();return matches.size()==1?matches.get(0):null;}
 private ModPacketCatalog(){}
}
